SCALE = 10_000  # venue encodes prices in 1/10,000ths of a dollar

def normalise(raw):
    return {
        "symbol": raw["sym"].decode().replace(" US", ""),
        "price": raw["px"] / SCALE,   # 1,204,551 -> 120.4551
        "qty": raw["qty"],
        "side": "buy" if raw["flags"] & 0x01 else "sell",
    }

print(normalise({"sym": b"XYZ US", "px": 1_204_551, "qty": 300, "flags": 1})["price"])
